_UPGRADE_JS_POLISH = r"""
function polishDashboardTables() {
  document.querySelectorAll("table.fb-table").forEach(function (table) {
    if (!table.parentElement || table.parentElement.classList.contains("fb-table-wrap")) return;
    var wrap = document.createElement("div");
    wrap.className = "fb-table-wrap";
    table.parentNode.insertBefore(wrap, table);
    wrap.appendChild(table);
  });
  document.querySelectorAll(".fb-vvalue,.fb-vlabel").forEach(function (el) {
    el.style.fontSize = "12px";
  });
}
(function () {
  function run() {
    polishDashboardTables();
  }
  run();
  window.addEventListener("load", run);
  var mainEl = document.querySelector(".main");
  if (mainEl && window.MutationObserver) {
    var timer = null;
    var observer = new MutationObserver(function () {
      if (timer) clearTimeout(timer);
      timer = setTimeout(run, 80);
    });
    observer.observe(mainEl, { childList: true, subtree: true });
  }
})();
"""

